h=AccretionHistory(.105,1.,.1);h.advance(1,new_phellem_thickness_m=.0003,new_density_kg_m3=240,identity='old');triangle=np.array([[0.,0.],[.02,0.],[.002,.006]]);old0,x0,m0=make_cohort_cell(h,'old',triangle,2.8e6,.28);E0,g0,_=old0.evaluate(x0);h.advance(2,.001,new_phellem_thickness_m=.00025,new_density_kg_m3=240,identity='young');old,xold,om=make_cohort_cell(h,'old',triangle,2.8e6,.28);young,xy,ym=make_cohort_cell(h,'young',triangle,2.8e6,.28);Eold,gold,vold=old.evaluate(xold);Ey,gy,vy=young.evaluate(xy)
